#include <iostream>
#include <string>
#include <utility>

class Cuenta {
public:
    Cuenta(std::string titular, double saldo_inicial)
        : titular_(std::move(titular)), saldo_(saldo_inicial) {
        if (saldo_ < 0.0) {
            saldo_ = 0.0;
        }
        ++cuentas_;
    }

    ~Cuenta() { --cuentas_; }

    bool retirar(double monto) {
        if (monto <= 0.0 || monto > saldo_) {
            return false;
        }
        saldo_ -= monto;
        return true;
    }

    void mostrar() const {
        std::cout << titular_ << ": " << saldo_ << '\n';
    }

    static int activas() { return cuentas_; }

private:
    std::string titular_;
    double saldo_;
    static int cuentas_;
};

int Cuenta::cuentas_ = 0;

int main() {
    Cuenta a{"Ana", 100.0};
    {
        Cuenta b{"Luis", 50.0};
        std::cout << Cuenta::activas() << '\n';
        b.retirar(20.0);
        b.mostrar();
    }
    std::cout << Cuenta::activas() << '\n';
    a.mostrar();
    std::cout << a.retirar(500.0) << '\n';
    return 0;
}

#ifndef ESCALADOR_H
#define ESCALADOR_H

#include <vector>

class Escalador {
public:
    Escalador(double minimo, double maximo);
    std::vector<double> aplicar(const std::vector<double>& datos) const;

    double minimo() const { return minimo_; }
    double maximo() const { return maximo_; }

private:
    double minimo_;
    double maximo_;
};

#endif

#include "escalador.h"

#include <stdexcept>

Escalador::Escalador(double minimo, double maximo)
    : minimo_(minimo), maximo_(maximo) {
    if (maximo_ <= minimo_) {
        throw std::invalid_argument("maximo debe ser mayor que minimo");
    }
}

std::vector<double> Escalador::aplicar(const std::vector<double>& datos) const {
    std::vector<double> salida;
    salida.reserve(datos.size());
    const double rango = maximo_ - minimo_;
    for (double x : datos) {
        salida.push_back((x - minimo_) / rango);
    }
    return salida;
}

#include "escalador.h"

#include <iomanip>
#include <iostream>
#include <vector>

int main() {
    const Escalador escalador{0.0, 10.0};
    const std::vector<double> datos{2.0, 5.0, 9.0};

    for (double x : escalador.aplicar(datos)) {
        std::cout << std::fixed << std::setprecision(2) << x << ' ';
    }
    std::cout << '\n';
    return 0;
}

