#include <iostream>
#include <string>
#include <utility>

class CuentaBancaria {
public:
    CuentaBancaria(std::string titular, double saldo)
        : titular_(std::move(titular)), saldo_(saldo < 0.0 ? 0.0 : saldo) {}

    bool depositar(double monto) {
        if (monto <= 0.0) {
            return false;
        }
        saldo_ += monto;
        return true;
    }

    bool retirar(double monto) {
        if (monto <= 0.0 || monto > saldo_) {
            return false;
        }
        saldo_ -= monto;
        return true;
    }

    double saldo() const { return saldo_; }
    const std::string& titular() const { return titular_; }

private:
    std::string titular_;
    double saldo_;
};

int main() {
    CuentaBancaria c{"Ana", 100.0};
    std::cout << c.depositar(50.0) << ' ' << c.saldo() << '\n';
    std::cout << c.retirar(500.0) << ' ' << c.saldo() << '\n';
    std::cout << c.titular() << '\n';
    return 0;
}

#include <algorithm>
#include <iostream>
#include <numeric>
#include <stdexcept>
#include <utility>
#include <vector>

class Dataset {
public:
    explicit Dataset(std::vector<double> valores)
        : valores_(std::move(valores)) {
        if (valores_.empty()) {
            throw std::invalid_argument("el dataset no puede estar vacio");
        }
        ++instancias_;
    }

    double media() const {
        const double suma = std::accumulate(valores_.begin(), valores_.end(), 0.0);
        return suma / static_cast<double>(valores_.size());
    }

    double rango() const {
        const auto [minimo, maximo] =
            std::minmax_element(valores_.begin(), valores_.end());
        return *maximo - *minimo;
    }

    static int instancias() { return instancias_; }

private:
    std::vector<double> valores_;
    static int instancias_;
};

int Dataset::instancias_ = 0;

int main() {
    const Dataset d{std::vector<double>{2.0, 4.0, 9.0}};
    std::cout << d.media() << '\n';
    std::cout << d.rango() << '\n';
    std::cout << Dataset::instancias() << '\n';
    return 0;
}

